# Three rate-limit counters, limit 5 per window of 10 seconds.
LIMIT, W = 5, 10.0

def fixed(times):
    counts, out = {}, []
    for t in times:
        w = int(t // W)                  # which window this time falls in
        if counts.get(w, 0) < LIMIT:
            counts[w] = counts.get(w, 0) + 1; out.append(1)
        else:
            out.append(0)
    return out

def log(times):
    kept, out = [], []                   # O(N) memory: one timestamp each
    for t in times:
        kept = [x for x in kept if x > t - W]   # drop entries outside (t-W, t]
        if len(kept) < LIMIT:
            kept.append(t); out.append(1)
        else:
            out.append(0)
    return out

def counter(times):
    prev, cur, wid, out = 0, 0, 0, []    # O(1) memory: two counts
    for t in times:
        w = int(t // W)
        if w != wid:                     # moved to a new window
            prev = cur if w == wid + 1 else 0
            cur, wid = 0, w
        est = prev * (1 - (t % W) / W) + cur   # weighted estimate
        if est < LIMIT:
            cur += 1; out.append(1)
        else:
            out.append(0)
    return out

# 5 requests at the end of window 0, then 5 right after the boundary
times = [6, 7, 8, 9, 9.5, 10.1, 10.2, 10.3, 10.4, 10.5, 15, 19]
print("times       ", times)
for name, f in (("fixed", fixed), ("sliding log", log), ("sliding ctr", counter)):
    r = f(times)
    print("%-12s %s allowed=%d" % (name, r, sum(r)))
